import json
from pathlib import Path
p=Path(__file__).resolve().parent
s=json.loads((p/'summary.json').read_text());m=json.loads((p/'manifest.json').read_text());v=json.loads((p/'verification.json').read_text())
lines=['# GA8 exhaustive phase-1 forward test','',f"All **{s['tested']:,} / {s['eligible']:,}** distinct training qualifiers tested independently on 2024. No top-N cap, forward fitting, or selection.",'',f"Training: 2022-01-01 ≤ date < 2024-01-01. Gates: {m['training_gate']}. Enumerated {m['distinct_phase1_behaviors']:,} distinct phase-1 behaviors across the evaluated catalog, current and archived generation journals, and frozen stop checkpoint/status. No conflicting qualifying training metrics.",'','Each replay starts with $100,000 fresh cash, uses 252 identical sessions (2024-01-02 through 2024-12-31), and fixed GA8 execution. Trade count means closed trades. Forward success applies the same gates; benchmark outperformance means higher final NAV.', '',f"Forward successes: **{s['forward_successes']:,} / {s['tested']:,} ({s['forward_success_rate']:.2%})**.",'','| Benchmark | CAGR | MDD | Calmar | Final NAV | Qualifiers beating it |','|---|---:|---:|---:|---:|---:|']
for name,b in s['benchmarks'].items():lines.append(f"| {name} | {b['cagr']:.2%} | {b['max_drawdown']:.2%} | {b['calmar']:.3f} | ${b['final_nav']:,.2f} | {s['benchmark_wins'][name]:,} / {s['tested']:,} |")
lines += ['','QQQ was absent from DEV79; no QQQ parquet found under /opt/mts. No substitute was generated.','','## Distributions','','| Period / metric | Min | 5th | 25th | Median | 75th | 95th | Max |','|---|---:|---:|---:|---:|---:|---:|---:|']
for period,ds in s['distributions'].items():
 for metric,d in ds.items():
  fmt=(lambda x:f'{x:.2%}') if metric in ('cagr','max_drawdown') else (lambda x:f'{x:,.2f}')
  lines.append('| '+period+' / '+metric+' | '+' | '.join(fmt(d[k]) for k in ['min','p05','p25','median','p75','p95','max'])+' |')
for label in ['winners','losers']:
 lines += ['',f'## {label.capitalize()} by forward NAV','','Descriptive ranking after every qualifier was tested; these are not selections for further tuning.','','| ID | Train CAGR | Train MDD | Forward CAGR | Forward MDD | Forward Calmar | Forward NAV | Closed trades |','|---|---:|---:|---:|---:|---:|---:|---:|']
 for r in s[label]:
  a,b=r['training'],r['forward'];lines.append(f"| {r['id']} | {a['cagr']:.2%} | {a['max_drawdown']:.2%} | {b['cagr']:.2%} | {b['max_drawdown']:.2%} | {b['calmar']:.3f} | ${b['final_nav']:,.2f} | {b['closed_trades']} |")
lines += ['','## Artifacts and verification','','- `per_chromosome.csv`: every qualifier with training/forward CAGR, MDD, Calmar, NAV, closed trades, success and benchmark flags.','- `qualifiers.json`: frozen genomes, managers, original IDs, training metrics and provenance counts.','- `training_observations.jsonl` and `catalog_snapshot.sqlite`: retained evaluation metadata and original catalog.','- `manifest.json` and `data_metadata.json`: source hashes, cohort rules, execution conventions and data limitations.','- `results.jsonl`, `checkpoint.json`: durable per-chromosome results; rerun `/opt/mts/.venv/bin/python ga8_forward_all_20261029/run_all.py` from repository root to resume.','- `verification.json`: independent SQL gate count, complete unique coverage, unchanged source hashes, three training parity checks, and exact previous-winner/benchmark parity.','','Production GA8 and GA9 were not modified. Other existing forward tasks were left untouched. Python sources were copied locally before replay so concurrent edits could not alter this run.','','Limitations: retrospectively selected DEV79 universe with unproven full historical PIT and delisted coverage; chronological out-of-training evaluation rather than a prospectively sealed experiment. Equal weight uses 79 fixed cash sleeves with GEV cash until regular-way listing. Costs are 5bp slippage plus 1bp commission per fill; dividend receivables are nonspendable; terminal holdings are marked without liquidation.']
(p/'REPORT.md').write_text('\n'.join(lines)+'\n')
